<?php echo "HTTP test\n"; $ch = curl_init("https://latajada.menugo.local/carta"); curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true,CURLOPT_SSL_VERIFYPEER=>false,CURLOPT_SSL_VERIFYHOST=>false,CURLOPT_TIMEOUT=>10,CURLOPT_HTTPHEADER=>["Accept: text/html"]]); $b=curl_exec($ch); $c=curl_getinfo($ch,CURLINFO_HTTP_CODE); $e=curl_error($ch); curl_close($ch); echo "HTTP: $c\n"; echo "Error: $e\n"; echo "CSRF: ".(str_contains($b,"csrf-token")?"SI":"NO")."\n";